"""Fusion 360 script: chip chip2_encapsulation_emulsion_break_capsule_wash_curing (23.5 x 32 mm), generated by autochip/cad.py from chips/chip2_encapsulation_emulsion_break_capsule_wash_curing.json.
Run it in Fusion: Utilities > Scripts and Add-Ins, or send it through the Fusion MCP execute_code tool
(then set PARTS_DIR first). It
  1. imports every placed part (parts/<module>.stl, mm, chip origin) as its own component,
  2. sketches the board outline, the port circles and every channel centreline ("channel paths"),
  3. sketches every channel as a closed outline at its true width ("channel outlines"), ready to
     extrude-cut 0.3 mm into the fluidic layer (top of the fluidic layer at z = 1.5 mm).
Fusion's API works in cm; the numbers below are mm and converted on the way in.
"""
import adsk.core, adsk.fusion
import os

try:
    PARTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "parts")
except NameError:
    PARTS_DIR = globals()["PARTS_DIR"]
BOARD = [23.5, 32.0]
PARTS = [["core_join", "merge"], ["core_mix", "mixer"], ["encap_junction", "droplet_junction"], ["capsule_trap", "trap_chamber"]]
CHANNELS = [["ch_inlet_1_core_join", 0.3, [[2.5, 26.67], [4.5, 26.67]]], ["ch_core_join_core_mix", 0.5, [[7.5, 26.67], [19.5, 26.67], [19.5, 22.86], [19.0, 22.86]]], ["ch_core_mix_encap_junction", 0.5, [[16.4, 22.86], [4.0, 22.86], [4.0, 17.26], [4.5, 17.26]]], ["ch_encap_junction_capsule_trap", 0.5, [[7.5, 17.26], [19.5, 17.26], [19.5, 12.93], [4.0, 12.93], [4.0, 6.96], [4.5, 6.96]]], ["ch_capsule_trap_outlet_1", 0.5, [[18.6421, 6.96], [21.0, 6.96]]], ["ch_core_solution_in_core_join", 0.2, [[6.0, 29.5], [6.0, 28.17]]], ["ch_shell_polymer_in_encap_junction", 0.2, [[6.0, 20.09], [6.0, 18.76]]], ["ch_fluorinated_oil_in_encap_junction", 0.2, [[6.0, 14.43], [6.0, 15.76]]], ["ch_emulsion_breaker_in_capsule_trap", 0.2, [[10.07, 11.43], [10.07, 10.4955]]], ["ch_wash_buffer_in_capsule_trap", 0.2, [[13.07, 11.43], [13.07, 10.4955]]], ["ch_capsule_trap_capsule_trap_waste_out", 0.2, [[11.57, 3.4245], [11.57, 2.5]]]]
OUTLINES = [["ch_inlet_1_core_join", [[2.5, 26.82], [4.5, 26.82], [4.5, 26.52], [2.5, 26.52]]], ["ch_core_join_core_mix", [[7.5, 26.92], [19.75, 26.92], [19.75, 22.61], [19.0, 22.61], [19.0, 23.11], [19.25, 23.11], [19.25, 26.42], [7.5, 26.42]]], ["ch_core_mix_encap_junction", [[16.4, 22.61], [4.25, 22.61], [4.25, 17.51], [4.5, 17.51], [4.5, 17.01], [3.75, 17.01], [3.75, 23.11], [16.4, 23.11]]], ["ch_encap_junction_capsule_trap", [[7.5, 17.51], [19.75, 17.51], [19.75, 12.68], [4.25, 12.68], [4.25, 7.21], [4.5, 7.21], [4.5, 6.71], [3.75, 6.71], [3.75, 13.18], [19.25, 13.18], [19.25, 17.01], [7.5, 17.01]]], ["ch_capsule_trap_outlet_1", [[18.6421, 7.21], [21.0, 7.21], [21.0, 6.71], [18.6421, 6.71]]], ["ch_core_solution_in_core_join", [[6.1, 29.5], [6.1, 28.17], [5.9, 28.17], [5.9, 29.5]]], ["ch_shell_polymer_in_encap_junction", [[6.1, 20.09], [6.1, 18.76], [5.9, 18.76], [5.9, 20.09]]], ["ch_fluorinated_oil_in_encap_junction", [[5.9, 14.43], [5.9, 15.76], [6.1, 15.76], [6.1, 14.43]]], ["ch_emulsion_breaker_in_capsule_trap", [[10.17, 11.43], [10.17, 10.4955], [9.97, 10.4955], [9.97, 11.43]]], ["ch_wash_buffer_in_capsule_trap", [[13.17, 11.43], [13.17, 10.4955], [12.97, 10.4955], [12.97, 11.43]]], ["ch_capsule_trap_capsule_trap_waste_out", [[11.67, 3.4245], [11.67, 2.5], [11.47, 2.5], [11.47, 3.4245]]]]
PORTS = [["inlet_1", 2.5, 26.67, 1.0], ["outlet_1", 21.0, 6.96, 1.0], ["core_solution_in", 6.0, 29.5, 1.0], ["shell_polymer_in", 6.0, 20.09, 1.0], ["fluorinated_oil_in", 6.0, 14.43, 1.0], ["emulsion_breaker_in", 10.07, 11.43, 1.0], ["wash_buffer_in", 13.07, 11.43, 1.0], ["capsule_trap_waste_out", 11.57, 2.5, 1.0]]


def P(xy, z=0.0):
    return adsk.core.Point3D.create(xy[0] / 10.0, xy[1] / 10.0, z / 10.0)


def run(context=None):
    app = adsk.core.Application.get()
    design = adsk.fusion.Design.cast(app.activeProduct)
    root = design.rootComponent
    for module_id, part in PARTS:
        occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
        comp = occ.component
        comp.name = module_id + " (" + part + ")"
        path = os.path.join(PARTS_DIR, module_id + ".stl")
        if design.designType == adsk.fusion.DesignTypes.ParametricDesignType:
            base = comp.features.baseFeatures.add()
            base.startEdit()
            comp.meshBodies.add(path, adsk.fusion.MeshUnits.MillimeterMeshUnit, base)
            base.finishEdit()
        else:
            comp.meshBodies.add(path, adsk.fusion.MeshUnits.MillimeterMeshUnit)
    sk = root.sketches.add(root.xYConstructionPlane)
    sk.name = "chip2_encapsulation_emulsion_break_capsule_wash_curing outline + ports + channel paths"
    lines = sk.sketchCurves.sketchLines
    lines.addTwoPointRectangle(P((0, 0)), P(BOARD))
    for pid, x, y, d in PORTS:
        sk.sketchCurves.sketchCircles.addByCenterRadius(P((x, y)), d / 20.0)
    for cid, width, pts in CHANNELS:
        for a, b in zip(pts[:-1], pts[1:]):
            lines.addByTwoPoints(P(a), P(b))
    sk2 = root.sketches.add(root.xYConstructionPlane)
    sk2.name = "chip2_encapsulation_emulsion_break_capsule_wash_curing channel outlines (true width)"
    for cid, pts in OUTLINES:
        for a, b in zip(pts, pts[1:] + pts[:1]):
            sk2.sketchCurves.sketchLines.addByTwoPoints(P(a), P(b))
    app.activeViewport.fit()
    return "imported %d parts, sketched %d channels and %d ports" % (len(PARTS), len(CHANNELS), len(PORTS))
